    return ''.join(c for c in s if not (c in seen or seen.add(c)))

def word_frequency(s):
    freq = {}
    for w in s.split():
        freq[w] = freq.get(w, 0) + 1
    return freq

def flatten(lst):
    out = []
    for x in lst:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

def dedupe(lst):
    seen = set()
    return [x for x in lst if not (x in seen or seen.add(x))]

def rotate(lst, k):
    k = k % len(lst)
    return lst[-k:] + lst[:-k]

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_perfect_square(n):
    if n < 0:
        return False
    r = int(n**0.5)
    return r*r == n

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def bubble_sort(arr):
    a = list(arr)
    for i in range(len(a)):
        for j in range(len(a) - i - 1):
            if a[j] > a[j+1]:
                a[j], a[j+1] = a[j+1], a[j]
    return a

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    m = len(arr) // 2
    L, R = merge_sort(arr[:m]), merge_sort(arr[m:])
    out, i, j = [], 0, 0
    while i < len(L) and j < len(R):
        if L[i] <= R[j]:
            out.append(L[i]); i += 1
        else:
            out.append(R[j]); j += 1
    return out + L[i:] + R[j:]

def find_index(lst, val):
