def selection_sort(arr):
    a = list(arr)
    for i in range(len(a)):
        m = min(range(i, len(a)), key=lambda k: a[k])
        a[i], a[m] = a[m], a[i]
    return a

def merge_sorted(a, b):
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    return out + a[i:] + b[j:]

class Stack:
    def __init__(self):
        self.items = []
    def push(self, x):
        self.items.append(x)
    def pop(self):
        return self.items.pop()
    def peek(self):
        return self.items[-1]

class Queue:
    def __init__(self):
        self.items = []
    def enqueue(self, x):
        self.items.append(x)
    def dequeue(self):
        return self.items.pop(0)

def group_by_first(words):
    out = {}
    for w in words:
        out.setdefault(w[0], []).append(w)
    return out

def squares(n):
    for i in range(n):
        yield i * i

def count_elements(lst):
    out = {}
    for x in lst:
        out[x] = out.get(x, 0) + 1
    return out
